<template><WorkspacePage title="操作日志" subtitle="审计管理操作和请求结果"><a-form v-show="showSearch" class="query-form" layout="inline"><a-form-item label="操作地址"><a-input v-model:value="queryParams.operIp" allow-clear /></a-form-item><a-form-item label="系统模块"><a-input v-model:value="queryParams.title" allow-clear /></a-form-item><a-form-item label="操作人员"><a-input v-model:value="queryParams.operName" allow-clear /></a-form-item><a-form-item label="类型"><a-select v-model:value="queryParams.businessType" allow-clear :options="typeOptions" /></a-form-item><a-form-item label="状态"><a-select v-model:value="queryParams.status" allow-clear :options="statusOptions" /></a-form-item><a-form-item label="操作时间"><a-range-picker v-model:value="dateRange" value-format="YYYY-MM-DD HH:mm:ss" show-time /></a-form-item><a-form-item><a-button type="primary" @click="handleQuery"><SearchOutlined />搜索</a-button><a-button @click="resetQuery"><ReloadOutlined />重置</a-button></a-form-item></a-form><div class="toolbar"><a-space><a-button danger :disabled="!ids.length" @click="handleDelete" v-hasPermi="['monitor:operlog:remove']"><DeleteOutlined />删除</a-button><a-button danger @click="handleClean" v-hasPermi="['monitor:operlog:remove']"><ClearOutlined />清空</a-button><a-button @click="handleExport" v-hasPermi="['monitor:operlog:export']"><DownloadOutlined />导出</a-button></a-space><a-button shape="circle" @click="showSearch=!showSearch"><FilterOutlined /></a-button></div><ResourceTable :columns="columns" :rows="operlogList" :loading="loading" :pagination="false" row-key="operId" :scroll="{x:1050}" @change="handleTableChange"><template #headerCell="{column}"><a-checkbox v-if="column.key==='select'" :checked="allSelected" :indeterminate="ids.length>0&&!allSelected" @change="toggleAll" /></template><template #bodyCell="{column,record}"><template v-if="column.key==='select'"><a-checkbox :checked="ids.includes(record.operId)" @change="e=>toggleRow(record,e.target.checked)" /></template><template v-else-if="column.key==='businessType'"><dict-tag :options="sys_oper_type" :value="record.businessType" /></template><template v-else-if="column.key==='status'"><dict-tag :options="sys_common_status" :value="record.status" /></template><template v-else-if="column.key==='operTime'">{{parseTime(record.operTime)}}</template><template v-else-if="column.key==='costTime'">{{record.costTime}}毫秒</template><template v-else-if="column.key==='action'"><a-button type="link" @click="handleDetail(record)" v-hasPermi="['monitor:operlog:query']"><EyeOutlined />详细</a-button></template></template></ResourceTable><a-pagination v-if="total>0" v-model:current="queryParams.pageNum" v-model:page-size="queryParams.pageSize" :total="total" show-size-changer @change="getList"/><OperlogDetail v-model:visible="detailVisible" :row="detailRow"/></WorkspacePage></template>
<script setup name="Operlog">
import{ClearOutlined,DeleteOutlined,DownloadOutlined,EyeOutlined,FilterOutlined,ReloadOutlined,SearchOutlined}from'@ant-design/icons-vue';import WorkspacePage from '@/components/Antd/WorkspacePage.vue';import ResourceTable from '@/components/Antd/ResourceTable.vue';import feedback from '@/plugins/antdFeedback';import OperlogDetail from './detail.vue';import{list,delOperlog,cleanOperlog}from'@/api/monitor/operlog'
const{proxy}=getCurrentInstance();const{sys_oper_type,sys_common_status}=proxy.useDict('sys_oper_type','sys_common_status');const operlogList=ref([]),detailVisible=ref(false),loading=ref(true),detailRow=ref({}),showSearch=ref(true),ids=ref([]),total=ref(0),dateRange=ref([]);const queryParams=reactive({pageNum:1,pageSize:10,operIp:undefined,title:undefined,operName:undefined,businessType:undefined,status:undefined,orderByColumn:'operTime',isAsc:'descending'});const typeOptions=computed(()=>sys_oper_type.value.map(x=>({label:x.label,value:x.value}))),statusOptions=computed(()=>sys_common_status.value.map(x=>({label:x.label,value:x.value})));const allSelected=computed(()=>operlogList.value.length>0&&operlogList.value.every(x=>ids.value.includes(x.operId)));const columns=[{title:'',key:'select',width:48},{title:'日志编号',dataIndex:'operId',key:'operId'},{title:'系统模块',dataIndex:'title',key:'title',ellipsis:true},{title:'操作类型',key:'businessType'},{title:'操作人员',dataIndex:'operName',key:'operName',sorter:true},{title:'操作地址',dataIndex:'operIp',key:'operIp'},{title:'操作状态',key:'status'},{title:'操作日期',dataIndex:'operTime',key:'operTime',width:180,sorter:true,defaultSortOrder:'descend'},{title:'消耗时间',dataIndex:'costTime',key:'costTime',width:110,sorter:true},{title:'操作',key:'action',width:90}]
async function getList(){loading.value=true;try{const r=await list(proxy.addDateRange({...queryParams},dateRange.value));operlogList.value=r.rows;total.value=r.total;ids.value=[]}finally{loading.value=false}}function handleQuery(){queryParams.pageNum=1;getList()}function resetQuery(){dateRange.value=[];Object.assign(queryParams,{pageNum:1,operIp:undefined,title:undefined,operName:undefined,businessType:undefined,status:undefined,orderByColumn:'operTime',isAsc:'descending'});getList()}function toggleRow(row,on){ids.value=on?[...new Set([...ids.value,row.operId])]:ids.value.filter(x=>x!==row.operId)}function toggleAll(e){ids.value=e.target.checked?operlogList.value.map(x=>x.operId):[]}function handleTableChange(_,__,s){if(!s.field)return;queryParams.orderByColumn=s.field;queryParams.isAsc=s.order==='ascend'?'ascending':'descending';getList()}function handleDetail(row){detailRow.value=row;detailVisible.value=true}async function handleDelete(row={}){try{const values=row.operId||ids.value;await feedback.confirm(`是否确认删除日志编号为"${values}"的数据项?`);await delOperlog(values);feedback.msgSuccess('删除成功');getList()}catch{}}async function handleClean(){try{await feedback.confirm('是否确认清空所有操作日志数据项?');await cleanOperlog();feedback.msgSuccess('清空成功');getList()}catch{}}function handleExport(){proxy.download('monitor/operlog/export',{...queryParams},`config_${Date.now()}.xlsx`)}getList()
</script><style scoped>.query-form{padding:16px;margin-bottom:12px;border:1px solid var(--workspace-border)}.toolbar{display:flex;justify-content:space-between;margin-bottom:12px}:deep(.ant-pagination){justify-content:flex-end;margin-top:14px}</style>
